import json, re, sys

base = "/Users/kristinarash/Library/Caches/sportsci-batch-96"
inputs = {d["id"]: d for d in json.load(open(base + "/inputs.json"))}
tax = json.load(open(base + "/taxonomy.json"))
ids = ["Q57", "Q58", "Q59", "Q60", "Q61", "Q62", "Q63", "Q64"]

for i in ids:
    d = json.load(open(base + "/drafts/%s.json" % i))
    src_ok = d["sourceFile"] == inputs[i]["sourceFile"]
    print(i, "sourceFile match:", src_ok)
    if not src_ok:
        print("   draft:", repr(d["sourceFile"]))
        print("   input:", repr(inputs[i]["sourceFile"]))
    if d["decision"] == "EXCLUDE":
        continue
    for k, key in [("studyDesign", "studyDesigns"), ("primaryDomain", "domains")]:
        if d[k] not in tax[key]:
            print("   BAD", k, repr(d[k]))
    for k, key in [("domains", "domains"), ("audiences", "audiences"), ("sports", "sports"), ("populations", "populations")]:
        for v in d[k]:
            if v not in tax[key]:
                print("   BAD", k, repr(v))
    if d["primaryDomain"] not in d["domains"]:
        print("   primaryDomain not in domains")
    p = d["paper"]
    for f, v in p.items():
        if f in ("year", "citation", "doi"):
            continue
        n = len([s for s in re.split(r"(?<=[.!?])\s+(?=[A-Z(])", v.strip()) if s])
        if n > 3:
            print("   %s sentences=%d" % (f, n))
    for f in ("evidenceSummary", "screeningLimitations"):
        n = len([s for s in re.split(r"(?<=[.!?])\s+(?=[A-Z(])", d[f].strip()) if s])
        print("   %s sentences=%d" % (f, n))

